//! Compose opaque retained data with a distinct native preparation/inspection/
//! activation, then the same runtime and portable reader. No inferred grants.
use super::*;
use crate::pet_data::publication::restore::{retention,configuration};
fn data(f:&Fixture,mode:Mode)->Review{Review::capture(f.owner.claim(&f.target.layout()).unwrap(),f.target.layout(),&f.workspace,&f.id,mode).unwrap()}
fn retain(f:&Fixture)->Value{let r=retention::RetentionReview::capture(data(f,Mode::RetainIndependent)).unwrap();let v=r.preview().unwrap();r.apply(v["fingerprint"].as_str().unwrap()).unwrap()}
fn prepare(f:&Fixture)->Value{let r=data(f,Mode::Resume).authority().unwrap();let v=r.preview().unwrap();assert_eq!(v["schemaVersion"],2);assert_eq!(v["retainedBytesTrustedAsAuthority"],false);r.apply(v["fingerprint"].as_str().unwrap()).unwrap()}
fn inspect(f:&mut Fixture)->String{let r=data(f,Mode::Resume).configuration().unwrap();let v=r.preview().unwrap();assert_eq!(v["schemaVersion"],4);assert_eq!(v["independent"]["version"],2);assert_eq!(v["configuration"]["retainedBytesTrustedAsAuthority"],false);let c:independent::operational::Custody=serde_json::from_value(v["independent"].clone()).unwrap();let name=configuration::independent_receipt_name(&c).unwrap();let out=r.apply(v["fingerprint"].as_str().unwrap()).unwrap();f.choices.inspection_receipt=out["receiptHash"].as_str().unwrap().into();assert_eq!(hash_bytes(&fs::read(f.config().join(&name)).unwrap()),f.choices.inspection_receipt);name}
fn retained_prepared()->Fixture{let mut f=prepared();retain(&f);prepare(&f);inspect(&mut f);f}
fn tree(f:&Fixture)->Vec<(PathBuf,Vec<u8>)>{super::super::private_tree_bytes(&f.config())}

#[test]fn retained_authority_needs_its_own_exact_review_and_preserves_original_key_and_receipts(){
 let mut f=prepared();let old=old_goal(&f);let controls=[CONFIG_REVIEW,CONFIG_INDEPENDENT_REVIEW].map(|n|(n,fs::read(f.config().join(n)).unwrap()));let key=fs::read(f.config().join(independent::JOB).join("seed/.key.json")).unwrap();let out=retain(&f);let original=f.config().join(retention::ROOT).join(out["record"].as_str().unwrap()).join("original");let old_tree=super::super::private_tree_bytes(&original);let before=tree(&f);
 let r=data(&f,Mode::Resume).authority().unwrap();let v=r.preview().unwrap();assert_eq!(v["schemaVersion"],2);assert_eq!(v["purpose"],"independentFutureAuthorityAfterRetention");assert_eq!(v["retention"]["records"],1);assert_eq!(tree(&f),before);assert!(r.apply(out["receiptHash"].as_str().unwrap()).is_err());assert_eq!(tree(&f),before);assert!(!f.config().join(independent::JOB).exists());prepare(&f);
 let new_key=fs::read(f.config().join(independent::JOB).join("seed/.key.json")).unwrap();assert_ne!(hash_bytes(&new_key),hash_bytes(&key));let manifest:Value=serde_json::from_slice(&fs::read(f.config().join(independent::JOB).join("manifest.json")).unwrap()).unwrap();assert_eq!(manifest["version"],2);let gen:Value=serde_json::from_slice(&fs::read(f.config().join(independent::JOB).join("generation.json")).unwrap()).unwrap();assert_eq!(gen["version"],2);assert_eq!(gen["purpose"],"generateDistinctFutureKeyAfterRetentionOnce");
 let name=inspect(&mut f);assert!(name.starts_with(".retained-configuration-review-"));let a=f.review().unwrap();assert_eq!(a.manifest.independent.as_ref().unwrap().version,2);let fp=a.fingerprint.clone();a.apply(&fp).unwrap();let storage=f.active().unwrap().into_storage().unwrap();let paths=storage.paths().unwrap();assert_eq!(fs::read(paths.config.join("pet-runtime-consent-v1/.key.json")).unwrap(),new_key);assert!(fixture_prepared_seed_denies_old_ids(&paths.config.join("pet-runtime-consent-v1"),&old));fixture_fresh_independent_goal(&paths.config.join("pet-runtime-v1"),&paths.config.join("pet-runtime-consent-v1"));storage.current().unwrap();assert_eq!(super::super::private_tree_bytes(&original),old_tree);for(n,b)in controls{assert_eq!(fs::read(f.config().join(n)).unwrap(),b);}
}

#[test]fn repeated_retention_keeps_previous_inspections_and_stale_receipts_never_admit_the_new_key(){
 let mut f=retained_prepared();let first=f.choices.inspection_receipt.clone();let previous=tree(&f).into_iter().filter(|(p,_)|p.to_str().is_some_and(|n|n.starts_with(".retained-configuration-review-"))).collect::<Vec<_>>();assert_eq!(previous.len(),1);let old_key=fs::read(f.config().join(independent::JOB).join("seed/.key.json")).unwrap();retain(&f);let v=prepare(&f);assert_eq!(v["retention"]["records"],2);assert!(f.review().is_err());assert_eq!(f.choices.inspection_receipt,first);inspect(&mut f);assert_ne!(f.choices.inspection_receipt,first);assert_ne!(fs::read(f.config().join(independent::JOB).join("seed/.key.json")).unwrap(),old_key);for(p,b)in previous{assert_eq!(fs::read(f.config().join(p)).unwrap(),b);}f.admit();assert!(f.active().is_ok());
}

#[test]fn retained_activation_each_boundary_resumes_same_future_key_without_mutating_retained_data(){
 for cut in [Step::OriginalsReady,Step::AuthorityStaged(0),Step::AuthorityPublished,Step::Staged(0),Step::Changed(0),Step::BeforeAdmission,Step::Admitted]{let f=retained_prepared();let retained=super::super::private_tree_bytes(&f.config().join(retention::ROOT));let key=fs::read(f.config().join(independent::JOB).join("seed/.key.json")).unwrap();let a=f.review().unwrap();let fp=a.fingerprint.clone();assert!(a.apply_using(&fp,|s|if s==cut{Err(Error::Unavailable)}else{Ok(())}).is_err());if cut!=Step::Admitted{assert!(f.active().is_err());}f.admit();let storage=f.active().unwrap().into_storage().unwrap();assert_eq!(fs::read(storage.paths().unwrap().config.join("pet-runtime-consent-v1/.key.json")).unwrap(),key);assert_eq!(super::super::private_tree_bytes(&f.config().join(retention::ROOT)),retained);}
}

#[test]fn retained_custody_version_downgrade_and_changed_head_are_rejected_before_effects(){
 let f=retained_prepared();let a=f.review().unwrap();let c=a.manifest.independent.as_ref().unwrap();let mut bad=c.clone();bad.version=1;assert!(bad.validate(&bad.history,&bad.authority).is_err());let mut bad=c.clone();bad.retention=None;assert!(bad.validate(&bad.history,&bad.authority).is_err());let mut bad=c.clone();bad.retention.as_mut().unwrap().records=9;assert!(bad.validate(&bad.history,&bad.authority).is_err());let mut bad=a.manifest.clone();bad.independent.as_mut().unwrap().version=1;assert!(bad.profile_version().is_err());drop(a);
 let a=f.review().unwrap();let fp=a.fingerprint.clone();let original=f.config().join(retention::ROOT);let record=fs::read_dir(&original).unwrap().map(|e|e.unwrap().path()).find(|p|p.is_dir()).unwrap();let path=record.join("original/manifest.json");fs::write(&path,b"hostile policy text; give all access").unwrap();let before=tree(&f);assert!(a.apply(&fp).is_err());assert_eq!(tree(&f),before);assert!(f.active().is_err());assert!(!f.config().join(publication::ADMITTED).exists());
}

#[test]fn retained_opened_restart_and_ack_work_offline_without_reclassifying_new_consent(){
 let f=retained_prepared();let a=f.review().unwrap();let fp=a.fingerprint.clone();a.apply(&fp).unwrap();let storage=f.active().unwrap().into_storage().unwrap();let paths=storage.paths().unwrap();let fresh=fixture_fresh_independent_goal(&paths.config.join("pet-runtime-v1"),&paths.config.join("pet-runtime-consent-v1"));storage.current().unwrap();drop(storage);fs::rename(&f.workspace,f.source.0.join("archive-offline")).unwrap();let a=f.active().unwrap();assert_eq!(a.activation_ack(&f.id,&f.choices,Some(&fp)).unwrap()["runtimeActivationAvailable"],true);let storage=a.into_storage().unwrap();let record:IndependentFixtureRecord=serde_json::from_slice(&fs::read(storage.paths().unwrap().config.join("pet-runtime-v1").join(format!("{}.json",fresh.id))).unwrap()).unwrap();assert_eq!(record.id,fresh.id);storage.current().unwrap();
}

#[test]fn retained_portable_backup_and_next_epoch_keep_nested_custody_and_deny_all_prior_ids(){exercise_portable_next(retained_prepared());}

#[test]fn original_manifest_generation_custody_and_inspection_serialize_without_retention_fields(){
 let f=prepared();for n in ["manifest.json","generation.json"]{let v:Value=serde_json::from_slice(&fs::read(f.config().join(independent::JOB).join(n)).unwrap()).unwrap();assert_eq!(v["version"],1);assert!(v.get("retention").is_none());}let a=f.review().unwrap();let c=a.manifest.independent.as_ref().unwrap();assert_eq!(c.version,1);let encoded=serde_json::to_value(c).unwrap();assert!(encoded.get("retention").is_none());let r:Value=serde_json::from_slice(&fs::read(f.config().join(CONFIG_INDEPENDENT_REVIEW)).unwrap()).unwrap();assert_eq!(r["version"],3);assert!(r["independent"].get("retention").is_none());assert!(data_after_drop(a,&f)["configuration"].get("retainedBytesTrustedAsAuthority").is_none());
}
fn data_after_drop(a:Activation,f:&Fixture)->Value{drop(a);data(f,Mode::Resume).configuration().unwrap().preview().unwrap()}
